import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, ROOT)

import docx_kit as k
from docx.shared import Pt, Cm, RGBColor
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

OUT = os.path.join(ROOT, "docs", "20-性能预算-讲懂版.docx")

def _mono(r):
    """把一段 run 变成等宽字体（用于行内代码）。"""
    r.font.name = "Consolas"
    rpr = r._element.get_or_add_rPr()
    rf = rpr.find(qn("w:rFonts"))
    if rf is None:
        rf = OxmlElement("w:rFonts")
        rpr.append(rf)
    for a in ("w:ascii", "w:hAnsi"):
        rf.set(qn(a), "Consolas")
    rf.set(qn("w:eastAsia"), k.CN)
    r.font.color.rgb = RGBColor(0x2F, 0x51, 0x7A)


def rich(p, s, size=10.5, color=k.K):
    """docx_kit.rich 的加强版：除 **加粗** 外，还认 `行内代码`。"""
    for i, part in enumerate(s.split("**")):
        bold = i % 2 == 1
        for j, seg in enumerate(part.split("`")):
            if not seg:
                continue
            r = p.add_run(seg)
            k.set_run(r, size, bold, color)
            if j % 2 == 1:
                _mono(r)


k.rich = rich




def cmd(doc, text, note=None):
    """一条可直接抄的命令：灰底、等宽字体。"""
    p = doc.add_paragraph()
    pf = p.paragraph_format
    pf.left_indent = Cm(0.6)
    pf.space_before = Pt(3)
    pf.space_after = Pt(3)
    pf.line_spacing = 1.25
    pPr = p._p.get_or_add_pPr()
    shd = OxmlElement("w:shd")
    shd.set(qn("w:val"), "clear")
    shd.set(qn("w:color"), "auto")
    shd.set(qn("w:fill"), "F1F3F6")
    pPr.append(shd)
    r = p.add_run(text)
    r.font.size = Pt(9.5)
    r.font.name = "Consolas"
    rpr = r._element.get_or_add_rPr()
    rf = rpr.find(qn("w:rFonts"))
    if rf is None:
        rf = OxmlElement("w:rFonts")
        rpr.append(rf)
    for a in ("w:ascii", "w:hAnsi"):
        rf.set(qn(a), "Consolas")
    rf.set(qn("w:eastAsia"), k.CN)
    r.font.color.rgb = RGBColor(0x1B, 0x1B, 0x1B)
    if note:
        k.para(doc, note, size=9.5, indent=False, after=8)
    return p


